VALUES ('f_78bedc46245090a160d2dd', 'match3d-backend deploy log', 'application/vnd.google-apps.spreadsheet', '["d_cd7849ec043ab3da107f8c"]', 'douglas@harmonygames.co', '["arthur.blake@harmonygames.co", "oliver.brooks@harmonygames.co", "vincent.parker@harmonygames.co"]', '[{"email": "arthur.blake@harmonygames.co", "role": "reader"}, {"email": "oliver.brooks@harmonygames.co", "role": "reader"}, {"email": "vincent.parker@harmonygames.co", "role": "reader"}]', 'private', '["douglas@harmonygames.co"]', '2025-09-17T15:55:00Z', '2025-08-25T12:05:00Z', false, false);
