INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_470ae81236d5bd39045dc1', 'match3d-backend - prod deploys', 'douglas@harmonygames.co', '["arthur.blake@harmonygames.co", "oliver.brooks@harmonygames.co", "vincent.parker@harmonygames.co"]', 'private', E'match3d-backend - prod deploys\nHow prod works for the ZM backend since the prod env went up (match3d-backend#2).\n\nMerging doesn''t deploy anything. Dev is deployed by hand from main. Prod runs from the prod branch: to put a PR on prod you cherry-pick it onto prod, build a new zm-api task definition revision and update the service (steps on the CI/CD Pipeline & Branching page). Only the PRs picked onto prod are on prod.\n\nWhoever deploys a PR to prod comments on that PR with a line starting "prod:", the time in UTC and the task definition. That comment is what puts the PR on prod, not the merge and not a Slack message.\n\nA prod deploy only counts if the PR already had an Approve review from someone other than its author when it went out. Approving afterwards doesn''t fix it; redeploy.\n\nTo roll back, revert the pick on prod, redeploy and comment "rollback:" on the PR. A rollback takes the PR off prod whenever it happens, freeze or not, until a newer "prod:" comment.\n\nConsole changes and spreadsheet imports have no PR: they go in the deploy log, Console & imports tab, with what changed or what was imported, the target (dev or prod) and the time.\n\nFreezes: from the server freeze on the calendar until the beta ships, the Approve review has to be Arthur''s. Anything else deployed during the freeze gets rolled back at go/no-go.\n\nThe deploy log also has a Prod deploys tab as a quick list.\n', '[{"start": 0, "end": 31, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 31, "end": 1399, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'c79f398ccc', 'f_470ae81236d5bd39045dc1', '2025-06-01T18:30:00Z', '2025-09-25T16:40:00Z');
