VALUES ('page_dd_launch_server_signoff', 'space_OPS', 'page_ops_home', 'Domino Delights global launch - server sign-off', '<p>For the Domino Delights global launch hotfix window (May 2025).</p><p>Scope: ENG tickets labelled Hot Fix - Global Launch that were closed during the window.</p><p>A server fix counts as live once Douglas posts the deploy in #live-incidents.</p><p>During the launch freeze a backend hotfix can go out with Arthur''s thumbs-up in #live-incidents.</p><p>Douglas keeps the deploy list.</p>', 'storage', 'current', 1, 'user_EMPLOYEE_0025', '2025-05-12T15:04:00Z', '2025-05-12T15:04:00Z');
INSERT INTO confluence.confluence_page_versions (id, page_id, number, title, body, author_id, message, created_at)
VALUES ('ver_2ee4eb6acd67b53fc1013166dab4c1b5', 'page_dd_launch_server_signoff', 1, 'Domino Delights global launch - server sign-off', '<p>For the Domino Delights global launch hotfix window (May 2025).</p><p>Scope: ENG tickets labelled Hot Fix - Global Launch that were closed during the window.</p><p>A server fix counts as live once Douglas posts the deploy in #live-incidents.</p><p>During the launch freeze a backend hotfix can go out with Arthur''s thumbs-up in #live-incidents.</p><p>Douglas keeps the deploy list.</p>', 'user_EMPLOYEE_0025', NULL, '2025-05-12T15:04:00Z');
