INSERT INTO trello.trello_cards (id, name, "idBoard", "idList", "desc", pos, closed, due, "dueComplete", "idMembers_json", "idLabels_json", "idShort", "shortLink", "shortUrl", url, "dateLastActivity", cover_json, badges_json)
VALUES ('68dabfe9bc2e8b969782e22d', 'Beta sign-off - server side', '6851a6569f3bf818760632ab', '6851a674975da1fe76e70d93', E'For the Oct 10 beta. Douglas owns this one.\n1. Scope: ZOM tickets moved to Done after the beta prod cut (the first row of Douglas''s deploy log) through Sep 30, where the fix needed a server change. A server change is a match3d-backend PR, or a change made straight in the Nakama console and logged in the deploy log. Client-only fixes are out. Parent tickets don''t get a row of their own.\n2. One row per ticket: ticket, server change(s), on prod (Y/N).\n3. On prod means what the match3d-backend prod deploys doc says. Merged is not on prod.\n4. A ticket with more than one server change is on prod only if all of them are.\n5. Anything not on prod goes back to Todo with a comment saying which change still has to go out. Same ticket, no new ones.\n6. The register goes in the sign-off folder named on the ZM Beta page in Confluence.', 140737488658432.0, false, NULL, false, '[]', '[]', 80, NULL, NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/twZVoQXy/80-beta-sign-off-server-side', '2025-09-30T15:05:27Z', NULL, '{"attachments": 0, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 0, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 1, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}');
