VALUES ('68dac311754b38be05be7ea9', 'Beta sign-off - client side', '6851a6569f3bf818760632ab', '6851a674975da1fe76e70d93', E'For the Oct 10 beta. Oliver owns this one.\n1. Scope: ZOM tickets closed since Aug 15 that changed the client.\n2. One row per ticket: ticket, build it shipped in, verified (Y/N).\n3. On the beta build means in Android 0.3.122 / iOS 0.3.38 or later.\n4. Anything not in the build goes back to In Validation.\n5. The sheet goes in the client QA folder.', 140737488666624.0, false, NULL, false, '[]', '[]', 81, NULL, NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/ZWabErQX/81-beta-sign-off-client-side', '2025-09-29T17:34:09Z', NULL, '{"attachments": 0, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 0, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 0, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}');
